import { abs } from "@/lib/schema";
import { SITEMAP_IDS, sitemapSection } from "@/content/sitemapSections";

// Sitemap index at /sitemap.xml, pointing to the section sitemaps generated by app/sitemap.ts.
export const dynamic = "force-static";

/** Newest lastModified among a section's URLs (content dates, not build time). */
function sectionLastmod(id: string) {
  const d = (sitemapSection(id) ?? []).map((e) => (e.lastModified ? new Date(e.lastModified).getTime() : 0)).sort((a, b) => b - a)[0];
  return d ? `<lastmod>${new Date(d).toISOString()}</lastmod>` : "";
}

export function GET() {
  const body = `<?xml version="1.0" encoding="UTF-8"?>
<sitemapindex xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
${[...SITEMAP_IDS.map((id) => `  <sitemap><loc>${abs(`/sitemap/${id}.xml`)}</loc>${sectionLastmod(id)}</sitemap>`), `  <sitemap><loc>${abs("/sitemap/images.xml")}</loc></sitemap>`].join("\n")}
</sitemapindex>
`;
  return new Response(body, { headers: { "Content-Type": "application/xml; charset=utf-8" } });
}
